<script setup lang="ts">
import{ref,onMounted}from'vue';import{ElMessageBox}from'element-plus';import{request,post}from'../api/client'
interface Summary{totalBytes:number;limitBytes:number;level:string;files:Array<{name:string;size:number;modified:string}>}
const summary=ref<Summary|null>(null),rows=ref<Array<Record<string,unknown>>>([]),level=ref(''),busy=ref(false),error=ref('')
const bytes=(n:number)=>n<1024?n+' B':n<1048576?(n/1024).toFixed(1)+' KiB':(n/1048576).toFixed(2)+' MiB'
async function load(){busy.value=true;error.value='';try{[summary.value,rows.value]=await Promise.all([request<Summary>('/logs/summary'),request<typeof rows.value>(`/logs?limit=100&level=${encodeURIComponent(level.value)}`)])}catch(e){error.value=e instanceof Error?e.message:'日志读取失败'}finally{busy.value=false}}
async function clear(){try{await ElMessageBox.confirm('清理全部程序文件日志？数据库审计、Docker启动控制台日志不会删除。','清理日志',{type:'warning',confirmButtonText:'确认清理',cancelButtonText:'取消'});await post('/logs/clear',{confirm:true});await load()}catch(e){if(e instanceof Error)error.value=e.message}}
async function change(value:string){try{await post('/logs/level',{level:value});await load()}catch(e){error.value=e instanceof Error?e.message:'设置失败'}}
onMounted(load)
</script>
<template><section class="page-heading"><div><span class="page-kicker">SYSTEM / 日志</span><h1>程序日志</h1><p>JSON结构化事件 · 仅显示脱敏文件日志，恢复临时密码不进入此页面。</p></div><div class="heading-actions"><el-button :loading="busy" @click="load">刷新日志</el-button><el-button type="danger" plain @click="clear">清理日志</el-button></div></section><el-alert v-if="error" :title="error" type="error" :closable="false"/><section class="panel log-summary"><div><h2>日志大小</h2><strong>{{bytes(summary?.totalBytes??0)}}</strong><p class="muted">上限 {{bytes(summary?.limitBytes??0)}} · 自动轮转</p></div><div><label for="runtime-log-level">本次运行日志级别</label><el-select id="runtime-log-level" :model-value="summary?.level" @change="change"><el-option v-for="x in ['debug','info','warn','error']" :key="x" :label="x.toUpperCase()" :value="x"/></el-select><p class="field-hint">永久默认值在Compose配置。更改不回填过去的日志。</p></div></section><section class="panel section-gap"><div class="panel-title"><h2>最近日志</h2><el-select v-model="level" aria-label="日志级别筛选" @change="load"><el-option label="全部级别" value=""/><el-option v-for="x in ['debug','info','warn','error']" :key="x" :label="x.toUpperCase()" :value="x"/></el-select></div><div class="log-list"><article v-for="(row,index) in rows" :key="index" class="log-entry"><span :class="['severity',String(row.level).toLowerCase()]">{{row.level}}</span><time>{{row.time}}</time><strong>{{row.msg}}</strong><pre>{{JSON.stringify(Object.fromEntries(Object.entries(row).filter(([k])=>!['time','level','msg'].includes(k))),null,2)}}</pre></article></div><el-empty v-if="!busy&&!rows.length" description="没有符合筛选条件的日志"/></section><section class="panel"><h2>保留文件</h2><el-table :data="summary?.files??[]"><el-table-column prop="name" label="文件"/><el-table-column label="大小"><template #default="{row}">{{bytes(row.size)}}</template></el-table-column><el-table-column prop="modified" label="更新时间"/></el-table></section></template>
<style scoped>.log-summary{display:grid;grid-template-columns:1fr 1fr;gap:24px;margin-bottom:24px}.log-summary strong{display:block;font-size:30px;margin:14px 0}.log-summary label{display:block;margin-bottom:12px}.log-entry{display:grid;grid-template-columns:72px 1fr;gap:8px 16px;padding:18px 0;border-bottom:1px solid var(--border)}.log-entry strong,.log-entry pre{grid-column:2}.log-entry time{font-size:12px;color:var(--muted);overflow-wrap:anywhere}.log-entry pre{white-space:pre-wrap;overflow-wrap:anywhere;margin:0;font-size:12px;color:var(--muted)}.severity{font-size:12px;font-weight:700}.warn{color:#9d6900}.error{color:var(--el-color-danger)}.info{color:var(--el-color-primary)}@media(max-width:680px){.log-summary{grid-template-columns:1fr}.log-entry{grid-template-columns:60px minmax(0,1fr)}}
</style>
